const item = $input.first().json;

const prompt = `# Script Agent Prompt

You are a Script Agent for a production system that generates short vertical kids videos.

Your task:
Turn the structured creative brief into a shot-by-shot structure for a short vertical video for YouTube Shorts / Reels.

Language requirements:
- Write everything in English.
- The title must be in English.
- Scene content must be in English.
- Visual descriptions must be in English.
- Voiceover must be in simple natural English for children.
- On-screen text must be short English editing-layer text only.
- Do not use Russian.
- Do not use Cyrillic.
- Do not mix languages.

Important:
- Do not make an explanatory marketing video.
- Do not make a generic cute story without a retention mechanic.
- The video must work visually without any text inside the generated frame.
- Do not add text, letters, numbers, signs, subtitles, logos, UI screens, watermark or typography inside scene prompts.
- Any on-screen text will be added later in editing only.
- Use the selected trend format and creative control contracts as the source of truth.
- Avoid repeated default patterns unless selected_trend_format requires them.
- Use trend-native kids short-form mechanics freely, but keep one simple visual action per scene.
- Use premium crisp 3D kids animation, clean geometry, sharp readable silhouettes, stable object shapes, consistent materials, polished non-melting surfaces, crisp facial details and clean mobile-short composition.
- Reject claymation, plasticine look, waxy melting surfaces, blob morphing, liquid morphing, body forming from soft blobs, organic merging between separate objects, smeared details, muddy textures, warped faces, unstable limbs, extra body parts and object category drift.
- Wrong choices must never attach to the main character. Wrong pieces may move near Pip, bump gently, wobble or bounce away unchanged. Pip remains unchanged. No body merging. No organic fusion.
- Only the correct object may attach. If an object is incorrect, it must remain separate and unchanged.
- Scene 06 / Loop hint must stay in the same toy world: no doors, no windows, no interior room, no new location, no glass panel, no portal, no cut to another space; the next puzzle piece may only peek from the frame edge inside the same toy world.
- Prioritize trend diversity, fast recognition, repeatable format structure and high short-form retention.
- Content must be safe for children and family viewing.
- No fear, violence, weapons, fire, crashes, injury, medical scenes, dangerous actions, toxic behavior or adult context.
- Target duration: about ${item.duration_seconds || 18} seconds.
- Return strictly in Markdown.

## Input creative brief

ID:
${item.id || "idea_001"}

Topic:
${item.topic || ""}

Content category:
${item.content_category || ""}

Audience:
${item.audience || ""}

Platform:
${item.platform || ""}

Duration:
${item.duration_seconds || 18} seconds

Tone:
${item.tone || ""}

Goal:
${item.goal || ""}

Retention strategy:
${JSON.stringify(item.retention_strategy || {}, null, 2)}

Story premise:
${item.story_premise || ""}

Main character:
${JSON.stringify(item.main_character || {}, null, 2)}

Supporting character:
${JSON.stringify(item.supporting_character || {}, null, 2)}

World:
${JSON.stringify(item.world || {}, null, 2)}

Selected trend format:
${item.selected_trend_format || ""}

Novelty angle:
${item.novelty_angle || ""}

Central retention mechanic:
${item.central_retention_mechanic || ""}

Repeated patterns to avoid:
${JSON.stringify(item.repeated_patterns_to_avoid || [], null, 2)}

Character bible:
${JSON.stringify(item.character_bible || [], null, 2)}

Object bible:
${JSON.stringify(item.object_bible || [], null, 2)}

World bible:
${JSON.stringify(item.world_bible || {}, null, 2)}

Consistency groups:
${JSON.stringify(item.consistency_groups || [], null, 2)}

Central object:
${JSON.stringify(item.central_object || {}, null, 2)}

Scene contracts:
${JSON.stringify(item.scene_contracts || [], null, 2)}

Forbidden object substitutions:
${JSON.stringify(item.forbidden_object_substitutions || [], null, 2)}

Plot:
${JSON.stringify(item.plot || {}, null, 2)}

Visual direction:
${item.visual_direction || ""}

Scene generation rules:
${JSON.stringify(item.scene_generation_rules || {}, null, 2)}

Safety rules:
${JSON.stringify(item.safety_rules || [], null, 2)}

Trend replication rules:
${JSON.stringify(item.trend_replication_rules || [], null, 2)}

Negative generation rules:
${JSON.stringify(item.negative_generation_rules || [], null, 2)}

## Output requirements

Return Markdown strictly in this structure:

# ${item.id || "idea_001"}. Vertical Video Script

## 1. Video title

Short working title in English.

## 2. Video goal

1–2 sentences explaining the retention mechanic.

## 3. Hook

One strong visual situation for the first 1–2 seconds.
No text inside the generated frame.

## 4. Video structure

Create a table:

| Block | Time | Content | Visual | On-screen text |
|---|---:|---|---|---|

Required blocks:
- Hook
- Error
- Choice
- Action
- Payoff
- Loop hint

Rules:
- The “Content” column must be in English.
- The “Visual” column must be in English.
- The “On-screen text” column must be in English and used only as editing-layer text.
- In the “Visual” column, describe only what the video generator should see.
- The visual action must be understandable without words.
- Keep one clear action per scene.
- Do not include text, letters, logos, UI or signs in generated scene visuals.

## 5. Voiceover

Very short voiceover in simple English for children.
Use 4–7 short phrases.
No complex words.
No long dialogue.

## 6. On-screen text

List short English editing-layer captions.
Maximum 5 words per line.
Do not include these captions inside generated visuals.

## 7. Scene prompts

For each scene, generate from the matching scene_contract and include:
- scene number;
- what happens;
- visual style;
- camera movement;
- main object;
- character emotion;
- safety constraints;
- negative constraints.

Every scene must obey:
- one scene = one simple action;
- one main object only;
- no object morphing;
- no claymation;
- no plasticine look;
- no waxy melting surfaces;
- no blob morphing;
- no liquid morphing;
- no body forming from soft blobs;
- no organic merging between separate objects;
- no object substitution;
- no wrong object attachment;
- no sudden new props;
- no sudden new characters;
- no changing the central object into a different object;
- preserve the character_bible, object_bible, world_bible and consistency_groups.

Every scene prompt must explicitly include:
no text, no letters, no numbers, no subtitles, no signs, no logos, no watermark.

## 8. CTA

Create a soft loop-CTA for kids/family short-form.
No sales pressure.
No manipulative call to action.

## 9. 5 alternative hooks

Five alternative visual hook ideas for the first 1–2 seconds.

## Restrictions

- Do not add facts that are not present in the input brief.
- Do not use Russian or Cyrillic.
- Follow the selected trend format mechanics: pacing, hook structure, scene rhythm, object logic, choice/reveal/sorting logic, emotional trigger and payoff pattern.
- Do not use dangerous actions.
- Do not write long dialogue.
- Do not add text inside generated scenes.
- Make scenes suitable for Higgsfield keyframe/video generation.
`;

return [
  {
    json: {
      id: item.id || "idea_001",
      status: "script_prompt_ready",
      source: "build-script-prompt-from-parsed-idea-en",
      parsed_idea: item,
      prompt: prompt.trim(),
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;
const sourceItem = $items("Build Script Prompt")[0]?.json || {};
const id = item.id || sourceItem.id || sourceItem.parsed_idea?.id || "idea_001";

const scriptMarkdown =
  item.output?.[0]?.content?.[0]?.text ||
  item.output?.content?.[0]?.text ||
  item.text ||
  '';

return [
  {
    json: {
      id,
      script_markdown: scriptMarkdown,
      parsed_idea: sourceItem.parsed_idea || {},
      creative_control: sourceItem.parsed_idea || {},
      generated_at: new Date().toISOString(),
      source: 'openai',
    },
  },
];

const item = $input.first().json;

const scriptMarkdown = item.script_markdown || "";
const creativeControl = item.creative_control || item.parsed_idea || {};

function extractDurationSeconds(markdown) {
  const match =
    markdown.match(/Длительность:\s*(\d+)\s*сек/i) ||
    markdown.match(/(\d+)\s*секунд/i);

  if (!match) return 18;

  const value = Number(match[1]);
  return Number.isFinite(value) && value > 0 ? value : 18;
}

const durationSeconds = extractDurationSeconds(scriptMarkdown);

const videoPayload = {
  id: item.id || "idea_001",
  format: "vertical_video",
  aspect_ratio: "9:16",
  platform: "reels_tiktok_shorts",
  language: "ru",
  duration_seconds: durationSeconds,
  source: item.source || "openai",
  generated_at: item.generated_at,
  script_markdown: scriptMarkdown,
  creative_control: creativeControl,
  selected_trend_format: creativeControl.selected_trend_format || "",
  novelty_angle: creativeControl.novelty_angle || "",
  central_retention_mechanic: creativeControl.central_retention_mechanic || "",
  production_status: "script_ready",
  next_step: "video_generation",
  video_requirements: {
    resolution: "1080x1920",
    captions: true,
    voiceover: true,
    background_music: true,
    safe_zones: true
  }
};

return [
  {
    json: {
      id: item.id || "idea_001",
      video_payload: videoPayload
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      id: item.id,
      status: 'ready_for_video_generation',
      video_payload: item.video_payload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const videoPayload = item.video_payload || {};
const creativeControl = videoPayload.creative_control || item.creative_control || {};
const scriptMarkdown =
  videoPayload.script_markdown ||
  item.script_markdown ||
  "";

if (!scriptMarkdown) {
  throw new Error("script_markdown not found");
}

function cleanText(value) {
  return String(value || "")
    .replace(/\\n/g, "\n")
    .replace(/\r/g, "")
    .trim();
}

const markdown = cleanText(scriptMarkdown);

function extractSection(markdown, heading) {
  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(
    `##\\s*${escapedHeading}\\s*\\n([\\s\\S]*?)(?=\\n##\\s+|\\n#\\s+|$)`,
    "i"
  );

  const match = markdown.match(regex);
  return match ? match[1].trim() : "";
}

function firstNonEmptyLine(text) {
  return cleanText(text)
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .find(Boolean) || "";
}

function stripMarkdownListMarker(line) {
  return String(line || "")
    .replace(/^\s*[-*]\s+/, "")
    .replace(/^\s*\d+[.)]\s+/, "")
    .trim();
}

function parseListSection(sectionText) {
  return cleanText(sectionText)
    .split("\n")
    .map(stripMarkdownListMarker)
    .map((line) => line.replace(/^["“”]+|["“”]+$/g, "").trim())
    .filter(Boolean)
    .filter((line) => !line.startsWith("|"))
    .filter((line) => !/^[-:| ]+$/.test(line));
}

function parseVideoStructureTable(markdown) {
  const section =
    extractSection(markdown, "4. Video structure") ||
    extractSection(markdown, "Video structure") ||
    extractSection(markdown, "4. Структура ролика") ||
    extractSection(markdown, "Структура ролика");

  if (!section) return [];

  const lines = section
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const tableLines = lines.filter((line) => line.startsWith("|") && line.endsWith("|"));

  if (tableLines.length < 3) return [];

  const dataLines = tableLines.filter((line) => {
    const normalized = line.replace(/\s/g, "");
    return !normalized.includes("|---") && !normalized.includes("|:---");
  });

  const header = dataLines.shift();
  if (!header) return [];

  return dataLines.map((line, index) => {
    const cells = line
      .split("|")
      .slice(1, -1)
      .map((cell) => cell.trim());

    const [block, time, content, visual, onScreenText] = cells;

    return {
      scene: index + 1,
      block: block || `Scene ${index + 1}`,
      duration: time || "",
      content: content || "",
      visual: visual || "",
      on_screen_text: onScreenText || ""
    };
  }).filter((scene) => scene.content || scene.visual);
}

function extractTitle(markdown) {
  const sectionTitle =
    firstNonEmptyLine(extractSection(markdown, "1. Video title")) ||
    firstNonEmptyLine(extractSection(markdown, "Video title")) ||
    "";

  if (sectionTitle) return sectionTitle.replace(/^#+\s*/, "").trim();

  const h1 = markdown.match(/^#\s+(.+)$/m);
  if (h1) {
    return h1[1]
      .replace(/^idea_\d+\.\s*/i, "")
      .replace(/Vertical Video Script/i, "")
      .trim();
  }

  return "Untitled Short";
}

function extractVoiceover(markdown) {
  const section =
    extractSection(markdown, "5. Voiceover") ||
    extractSection(markdown, "Voiceover") ||
    "";

  const lines = parseListSection(section);

  if (lines.length > 0) {
    return lines.join("\n");
  }

  return cleanText(section);
}

function extractCaptions(markdown) {
  const section =
    extractSection(markdown, "6. On-screen text") ||
    extractSection(markdown, "On-screen text") ||
    "";

  return parseListSection(section);
}

function extractCTA(markdown) {
  const section =
    extractSection(markdown, "8. CTA") ||
    extractSection(markdown, "CTA") ||
    "";

  return firstNonEmptyLine(section);
}

const title = extractTitle(markdown);
const voiceover = extractVoiceover(markdown);
const captions = extractCaptions(markdown);
const scenes = parseVideoStructureTable(markdown);
const sceneContracts = Array.isArray(creativeControl.scene_contracts) ? creativeControl.scene_contracts : [];
const sceneDurationTargets = {
  scene_01: 2.5,
  scene_02: 2.5,
  scene_03: 3.0,
  scene_04: 3.0,
  scene_05: 4.0,
  scene_06: 3.0
};

function targetDurationForScene(sceneId) {
  return sceneDurationTargets[sceneId] || 3.0;
}

const scenesWithContracts = scenes.map((scene, index) => {
  const sceneNumber = scene.scene || index + 1;
  const sceneId = `scene_${String(sceneNumber).padStart(2, "0")}`;
  const contract = sceneContracts.find((candidate) =>
    candidate.scene_id === sceneId ||
    Number(candidate.scene_number) === Number(sceneNumber)
  ) || {};

  const targetSceneDurationSeconds = targetDurationForScene(sceneId);

  return {
    ...scene,
    scene_id: sceneId,
    target_scene_duration_seconds: targetSceneDurationSeconds,
    max_scene_duration_seconds: targetSceneDurationSeconds,
    scene_trim_required: true,
    selected_trend_format: contract.selected_trend_format || creativeControl.selected_trend_format || "",
    scene_contract: {
      scene_id: sceneId,
      scene_number: sceneNumber,
      target_scene_duration_seconds: targetSceneDurationSeconds,
      max_scene_duration_seconds: targetSceneDurationSeconds,
      scene_trim_required: true,
      selected_trend_format: contract.selected_trend_format || creativeControl.selected_trend_format || "",
      clear_action: contract.clear_action || scene.content || "",
      action_start_state: contract.action_start_state || "",
      action_end_state: contract.action_end_state || "",
      main_character_ids: Array.isArray(contract.main_character_ids) ? contract.main_character_ids : [],
      central_object_ids: Array.isArray(contract.central_object_ids) ? contract.central_object_ids : [],
      allowed_motion: contract.allowed_motion || scene.content || "",
      camera_motion: contract.camera_motion || "subtle stable camera, no sudden cuts",
      emotion: contract.emotion || "clear safe emotion",
      visual_style: contract.visual_style || creativeControl.world_bible?.visual_style || scene.visual || "bright toy-like 3D animation",
      background: contract.background || creativeControl.world_bible?.setting || creativeControl.world?.setting || "consistent safe kids world",
      objects_that_must_not_change: Array.isArray(contract.objects_that_must_not_change)
        ? contract.objects_that_must_not_change
        : [],
      forbidden_object_substitutions: Array.isArray(contract.forbidden_object_substitutions)
        ? contract.forbidden_object_substitutions
        : (Array.isArray(creativeControl.forbidden_object_substitutions) ? creativeControl.forbidden_object_substitutions : []),
      negative_constraints: Array.isArray(contract.negative_constraints)
        ? contract.negative_constraints
        : (Array.isArray(creativeControl.negative_generation_rules) ? creativeControl.negative_generation_rules : []),
      quality_positive_constraints: Array.isArray(contract.quality_positive_constraints) ? contract.quality_positive_constraints : [],
      quality_negative_constraints: Array.isArray(contract.quality_negative_constraints) ? contract.quality_negative_constraints : [],
      object_interaction_rules: Array.isArray(contract.object_interaction_rules) ? contract.object_interaction_rules : [],
      same_world_loop_constraints: Array.isArray(contract.same_world_loop_constraints) ? contract.same_world_loop_constraints : [],
      no_text_in_frame: contract.no_text_in_frame === true
    }
  };
});
const cta = extractCTA(markdown);

if (!Array.isArray(scenes) || scenes.length === 0) {
  throw new Error("Could not extract scenes from Markdown video structure table");
}

const videoPipelineJson = {
  id: item.id || videoPayload.id || "idea_001",
  title,
  duration_seconds: Number(videoPayload.duration_seconds || item.duration_seconds || 18),
  language: "en",
  aspect_ratio: videoPayload.aspect_ratio || item.aspect_ratio || "9:16",
  resolution: videoPayload.video_requirements?.resolution || "1080x1920",
  voiceover,
  captions,
  selected_trend_format: creativeControl.selected_trend_format || "",
  novelty_angle: creativeControl.novelty_angle || "",
  central_retention_mechanic: creativeControl.central_retention_mechanic || "",
  repeated_patterns_to_avoid: Array.isArray(creativeControl.repeated_patterns_to_avoid) ? creativeControl.repeated_patterns_to_avoid : [],
  character_bible: Array.isArray(creativeControl.character_bible) ? creativeControl.character_bible : [],
  object_bible: Array.isArray(creativeControl.object_bible) ? creativeControl.object_bible : [],
  world_bible: creativeControl.world_bible || {},
  consistency_groups: Array.isArray(creativeControl.consistency_groups) ? creativeControl.consistency_groups : [],
  scene_contracts: scenesWithContracts.map((scene) => scene.scene_contract),
  forbidden_object_substitutions: Array.isArray(creativeControl.forbidden_object_substitutions) ? creativeControl.forbidden_object_substitutions : [],
  negative_generation_rules: Array.isArray(creativeControl.negative_generation_rules) ? creativeControl.negative_generation_rules : [],
  scenes: scenesWithContracts,
  cta,
  source_script_format: "markdown"
};

return [
  {
    json: {
      id: item.id || videoPayload.id || "idea_001",
      status: "ready_for_video_pipeline",
      video_pipeline_json: videoPipelineJson,
      source_video_payload: videoPayload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const packages = item.scene_packages || [];

if (!Array.isArray(packages) || packages.length === 0) {
  throw new Error("scene_packages is empty or not an array");
}

return packages.map((scenePackage) => ({
  json: {
    id: item.id,
    title: item.title,
    language: item.language,
    duration_seconds: item.duration_seconds,
    aspect_ratio: item.aspect_ratio,
    ...scenePackage
  }
}));

const items = $input.all();

if (!items.length) {
  throw new Error("No scene packages found");
}

return items.map((inputItem) => {
  const item = inputItem.json;

  if (!item.keyframe_prompt) {
    throw new Error(`keyframe_prompt not found for ${item.scene_id || "unknown scene"}`);
  }

  return {
    json: {
      id: item.id,
      title: item.title,
      language: item.language || "en",
      duration_seconds: item.duration_seconds,
      aspect_ratio: item.aspect_ratio,

      scene_id: item.scene_id,
      scene_number: item.scene_number,
      block: item.block,
      duration: item.duration,
      content: item.content,
      visual: item.visual,
      on_screen_text: item.on_screen_text,

      source: "keyframe-generation-layer",
      provider: "higgsfield",
      model: "soul",
      soul_endpoint: "/v1/text2image/soul",

      dop_prompt: item.dop_prompt,
      motions: item.motions,

      soul_payload: {
        params: {
          seed: null,
          prompt: item.keyframe_prompt,
          quality: item.quality || "720p",
          batch_size: item.batch_size || 1,
          enhance_prompt: item.enhance_prompt ?? true,
          style_strength: item.style_strength ?? 1,
          width_and_height: item.width_and_height || "1152x2048"
        },
        webhook: null
      }
    }
  };
});

const item = $input.first().json;

if (item.status !== "completed") {
  return [
    {
      json: {
        status: "not_ready",
        provider_status: item.status,
        request_id: item.request_id,
        status_url: item.status_url,
        source: "higgsfield-soul"
      }
    }
  ];
}

const keyframeUrl = item.images?.[0]?.url;

if (!keyframeUrl) {
  throw new Error("Soul completed, but images[0].url was not found");
}

return [
  {
    json: {
      scene_id: "scene_01",
      keyframe_status: "ready",
      keyframe_request_id: item.request_id,
      keyframe_url: keyframeUrl,
      source: "higgsfield-soul",
      completed_at: new Date().toISOString()
    }
  }
];

const items = $input.all();

const PUBLIC_FILES_BASE_URL = String($env.PUBLIC_FILES_BASE_URL || "").trim();
const PUBLIC_FRAME_PUBLISH_MODE = String($env.PUBLIC_FRAME_PUBLISH_MODE || "github-runtime-branch").trim();
const PUBLIC_FRAME_PUBLIC_BASE_URL = String($env.PUBLIC_FRAME_PUBLIC_BASE_URL || "").trim();
const PUBLIC_FRAME_BRANCH = String($env.PUBLIC_FRAME_BRANCH || "runtime/storyboard-frames").trim();
const HIGGSFIELD_VIDEO_MODEL = String($env.HIGGSFIELD_VIDEO_MODEL || "dop-turbo").trim();
const HIGGSFIELD_DOP_ENDPOINT = String($env.HIGGSFIELD_DOP_ENDPOINT || "/higgsfield-ai/dop/turbo").trim();

function normalizeBaseUrl(value) {
  return String(value || "").trim().replace(/\/$/, "");
}

const normalizedPublicFilesBaseUrl = normalizeBaseUrl(PUBLIC_FILES_BASE_URL);
const normalizedRuntimePublicBaseUrl = normalizeBaseUrl(PUBLIC_FRAME_PUBLIC_BASE_URL);

if (!items.length) {
  throw new Error("No storyboard frame items found");
}

function hasValue(value) {
  return Array.isArray(value) ? value.length > 0 : Boolean(String(value || "").trim());
}

function isMainDataRawUrl(url) {
  return /raw\.githubusercontent\.com\/pavelorlanskii-ux\/content-machine\/main\/data\/storyboard-frames\//.test(String(url || ""));
}

function isRuntimeFrameUrl(url) {
  const value = String(url || "");
  return value.includes(`/${PUBLIC_FRAME_BRANCH}/data/storyboard-frames/`) ||
    (normalizedRuntimePublicBaseUrl && value.startsWith(`${normalizedRuntimePublicBaseUrl}/storyboard-frames/`));
}

function resolvePublicImageUrl(item) {
  if (item.public_image_url) {
    return String(item.public_image_url).trim();
  }

  if (!normalizedPublicFilesBaseUrl) {
    throw new Error(`public_image_url not found for ${item.scene_id || "unknown scene"}. Run Publish Storyboard Frames or set PUBLIC_FILES_BASE_URL for static fallback mode.`);
  }

  const relativePath = item.local_frame_file_path.replace(/^data\//, "");
  return `${normalizedPublicFilesBaseUrl}/${relativePath}`;
}

function validatePublicImageUrl(item, publicImageUrl) {
  const mode = item.public_frame_publish_mode || PUBLIC_FRAME_PUBLISH_MODE;

  if (!publicImageUrl) {
    throw new Error(`public_image_url is required before DoP for ${item.scene_id || "unknown scene"}`);
  }

  if (isMainDataRawUrl(publicImageUrl)) {
    throw new Error(`public_image_url points to stale main/data storyboard frames for ${item.scene_id || "unknown scene"}: ${publicImageUrl}`);
  }

  if (mode === "github-runtime-branch" && !isRuntimeFrameUrl(publicImageUrl)) {
    throw new Error(`public_image_url must point to ${PUBLIC_FRAME_BRANCH} or PUBLIC_FRAME_PUBLIC_BASE_URL for ${item.scene_id || "unknown scene"}: ${publicImageUrl}`);
  }
}

function validateFrameAspect(item) {
  const width = Number(item.frame_width);
  const height = Number(item.frame_height);
  const targetAspect = 9 / 16;
  const tolerance = 0.015;

  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0 || Math.abs(width / height - targetAspect) > tolerance) {
    throw new Error(`DoP input frame must be vertical 9:16, got ${item.frame_width || "unknown"}x${item.frame_height || "unknown"}.`);
  }
}

function validateDopPrompt(prompt) {
  const normalized = String(prompt || "").toLowerCase();
  const requiredPhrases = [
    "no claymation",
    "no plasticine",
    "no melting",
    "no object morphing",
