  }

  if (!Array.isArray(pipeline.scene_contracts) || pipeline.scene_contracts.length === 0) {
    missing.push("scene_contracts");
  }

  if (!hasValue(contract.scene_id || item.scene_id)) missing.push("scene_id");
  if (!hasValue(contract.clear_action || item.content)) missing.push("clear_action");
  if (!hasValue(contract.central_object_ids) && !hasValue(item.central_object?.object_name) && !hasValue(item.visual)) {
