  if (!hasValue(contract.negative_constraints) && !hasValue(item.negative_generation_rules)) missing.push("negative constraints");
  if (contract.no_text_in_frame !== true) missing.push("no_text_in_frame true");
  if (!hasValue(contract.forbidden_object_substitutions) && !hasValue(item.forbidden_object_substitutions)) {
    missing.push("forbidden_object_substitutions");
  }
  if (!hasValue(contract.objects_that_must_not_change)) missing.push("objects_that_must_not_change");

