const scored = items.map((item) => {
  const v = item.json;

  const joinedText = [
    v.title,
    v.description,
    v.channel_title,
    Array.isArray(v.tags) ? v.tags.join(" ") : ""
  ].join(" ");

  const ageDays = daysSince(v.published_at);
  const viewCount = Number(v.view_count || 0);
  const likeCount = Number(v.like_count || 0);
  const commentCount = Number(v.comment_count || 0);
  const durationSeconds = Number(v.duration_seconds || 0);

  const viewsPerDay = ageDays ? viewCount / ageDays : 0;
  const likeRate = viewCount > 0 ? likeCount / viewCount : 0;
  const commentRate = viewCount > 0 ? commentCount / viewCount : 0;

  const kidsSignalCount = countMatches(joinedText, positiveKidsSignals);
  const trendMechanicCount = countMatches(joinedText, trendMechanicSignals);

  const unsafeFlag = includesAny(joinedText, unsafeWords);
  const brandFlag = includesAny(joinedText, brandWords);
  const nonKidsFlag = includesAny(joinedText, adultOrNonKidsWords);

  const durationFit =
    durationSeconds >= 7 && durationSeconds <= 45
      ? 1
      : durationSeconds > 45 && durationSeconds <= 60
        ? 0.5
        : 0;

  const isLikelyKids = kidsSignalCount >= 2;
  const isLikelyTrendUseful = trendMechanicCount >= 1;

  let score = 0;

  score += Math.log10(viewCount + 1) * 18;
  score += Math.log10(viewsPerDay + 1) * 28;
  score += Math.min(likeRate * 1000, 20);
  score += Math.min(commentRate * 2000, 10);
  score += kidsSignalCount * 3;
  score += trendMechanicCount * 6;
  score += durationFit * 12;

  if (unsafeFlag) score -= 55;
  if (brandFlag) score -= 35;
  if (nonKidsFlag) score -= 25;
  if (!isLikelyKids) score -= 30;
  if (!isLikelyTrendUseful) score -= 12;

  const verdict =
    unsafeFlag
      ? "reject_unsafe"
      : brandFlag
        ? "reject_brand_risk"
        : !isLikelyKids
          ? "reject_not_kids"
          : durationFit === 0
            ? "reject_duration"
            : score >= 130
              ? "strong_candidate"
              : score >= 95
                ? "candidate"
                : "weak_candidate";

  return {
    json: {
      ...v,
      age_days: ageDays,
      views_per_day: Math.round(viewsPerDay),
      like_rate: Number(likeRate.toFixed(6)),
      comment_rate: Number(commentRate.toFixed(6)),
      kids_signal_count: kidsSignalCount,
      trend_mechanic_count: trendMechanicCount,
      duration_fit: durationFit,
      unsafe_flag: unsafeFlag,
      brand_flag: brandFlag,
      non_kids_flag: nonKidsFlag,
      trend_score: Number(score.toFixed(2)),
      verdict
    }
  };
});

