  }
}

function cropAndResize(source, cropX, cropY, cropWidth, cropHeight, targetWidth, targetHeight) {
  assertVerticalFrame(cropWidth, cropHeight);

  const output = new PNG({ width: targetWidth, height: targetHeight });

  for (let y = 0; y < targetHeight; y++) {
    const sourceY = cropY + Math.min(cropHeight - 1, Math.floor((y / targetHeight) * cropHeight));

    for (let x = 0; x < targetWidth; x++) {
      const sourceX = cropX + Math.min(cropWidth - 1, Math.floor((x / targetWidth) * cropWidth));
      const sourceIdx = (source.width * sourceY + sourceX) << 2;
      const targetIdx = (targetWidth * y + x) << 2;

      output.data[targetIdx] = source.data[sourceIdx];
      output.data[targetIdx + 1] = source.data[sourceIdx + 1];
      output.data[targetIdx + 2] = source.data[sourceIdx + 2];
      output.data[targetIdx + 3] = source.data[sourceIdx + 3];
    }
  }

  assertVerticalFrame(output.width, output.height);
  return output;
}

