        instructions: [
          "Speak this as one short line for a vertical animated kids video.",
          `Delivery: ${scene.delivery || "warm, playful and clear"}.`,
          `The rendered scene duration is ${targetDuration.toFixed(2)} seconds.`,
          `The spoken line should fit comfortably within about ${maxSpeechDuration.toFixed(2)} seconds.`,
          "Keep it natural, bright, soft, and friendly.",
          "Do not rush, but keep the line compact.",
          "Do not sound robotic, harsh, scary, or overly babyish."
        ].join(" "),
        response_format: "mp3",
        speed: 0.95
      },

      source_voiceover_plan: item,
      completed_at: new Date().toISOString()
    }
  };
});

const now = new Date();

return [
  {
    json: {
      run_mode: "manual_test",
      trigger_source: "manual",
      run_id: `manual_${now.toISOString().replace(/[:.]/g, "-")}`
    }
  }
];

const now = new Date();

return [
  {
    json: {
      run_mode: "daily_auto",
      trigger_source: "schedule",
      run_id: `daily_${now.toISOString().replace(/[:.]/g, "-")}`
    }
  }
];

const statusItems = $input.all();
const pollInputItems = $items("Wait for DoP Render");
const sourceItems = $items("Build DoP Payload");

const maxAttempts = 10;
const waitSeconds = 60;

if (!statusItems.length) {
  throw new Error("No DoP status items found");
}

if (statusItems.length !== pollInputItems.length) {
  throw new Error(`DoP poll item count mismatch: statusItems=${statusItems.length}, pollInputItems=${pollInputItems.length}`);
}

if (statusItems.length !== sourceItems.length) {
  throw new Error(`DoP source item count mismatch: statusItems=${statusItems.length}, sourceItems=${sourceItems.length}`);
}

const mergedItems = statusItems.map((statusItem, index) => {
  const status = statusItem.json;
  const previous = pollInputItems[index].json;
  const source = sourceItems[index].json;
  const attempt = Number(previous.dop_poll_attempt || 0) + 1;

  return {
    json: {
      ...previous,
      ...status,

      request_id: status.request_id || previous.request_id,
      status_url: status.status_url || previous.status_url,
      cancel_url: status.cancel_url || previous.cancel_url,
      video: status.video || previous.video,

      scene_id: source.scene_id || previous.scene_id,
      scene_number: source.scene_number || previous.scene_number,
      public_image_url: source.public_image_url || previous.public_image_url,
      dop_prompt: source.dop_prompt || previous.dop_prompt,
      source_dop_payload: source,

      dop_poll_attempt: attempt,
      dop_poll_max_attempts: maxAttempts,
      dop_poll_wait_seconds: waitSeconds
    }
  };
});

const completedItems = mergedItems.filter((item) => item.json.status === "completed");
const pendingItems = mergedItems.filter((item) => ["queued", "in_progress"].includes(item.json.status));
const failedItems = mergedItems.filter((item) => !["completed", "queued", "in_progress"].includes(item.json.status));

if (failedItems.length) {
  const diagnostics = failedItems
    .map((item) => {
      const json = item.json;
      return `${json.scene_id || "unknown_scene"} / ${json.request_id || "unknown_request"} / ${json.status || "unknown_status"}`;
    })
    .join("; ");

  throw new Error(`DoP render failed or returned an unsupported status: ${diagnostics}`);
}

const pendingCount = pendingItems.length;
const completedCount = completedItems.length;
const allCompleted = pendingCount === 0;

const annotatedItems = mergedItems.map((item) => ({
  json: {
    ...item.json,
    dop_poll_pending_count: pendingCount,
    dop_poll_completed_count: completedCount,
    dop_poll_all_completed: allCompleted
  }
}));

if (!allCompleted) {
  const attempt = Math.max(...annotatedItems.map((item) => Number(item.json.dop_poll_attempt || 0)));

  if (attempt >= maxAttempts) {
    const diagnostics = pendingItems
      .map((item) => {
        const json = item.json;
        return `${json.scene_id || "unknown_scene"} / ${json.request_id || "unknown_request"} / ${json.status || "unknown_status"}`;
      })
      .join("; ");

    throw new Error(`DoP renders did not complete after ${maxAttempts} attempts (${maxAttempts * waitSeconds} seconds). Pending: ${diagnostics}`);
  }
}

return annotatedItems;

const items = $input.all();

if (!items.length) {
  throw new Error("No storyboard frame items found to publish");
}

const publishMode = String($env.PUBLIC_FRAME_PUBLISH_MODE || "github-runtime-branch").trim();
const runtimeRepo = String($env.PUBLIC_FRAME_REPO || "pavelorlanskii-ux/content-machine").trim();
const runtimeBranch = String($env.PUBLIC_FRAME_BRANCH || "runtime/storyboard-frames").trim();
const configuredRuntimeBaseUrl = String($env.PUBLIC_FRAME_PUBLIC_BASE_URL || "").trim();
const fallbackStaticBaseUrl = String($env.PUBLIC_FILES_BASE_URL || "").trim();

function normalizeBaseUrl(value) {
  return String(value || "").trim().replace(/\/$/, "");
}

function toRuntimeRepoPath(item) {
  const frameFilePath = String(item.frame_file_path || "").trim();
  const framePathFromFilesDir = frameFilePath.startsWith("/files/data/")
    ? `data/${frameFilePath.slice("/files/data/".length)}`
    : frameFilePath;
  const localPath = String(item.local_frame_file_path || framePathFromFilesDir || "").trim();

  if (!localPath) {
    throw new Error(`local_frame_file_path not found for ${item.scene_id || "unknown scene"}`);
  }

  return localPath.startsWith("data/") ? localPath : `data/${localPath.replace(/^[/]+/, "")}`;
}

function publicPathFromRuntimeRepoPath(repoPath) {
  return repoPath.startsWith("data/") ? repoPath.slice("data/".length) : repoPath;
}

const runtimeBaseUrl = normalizeBaseUrl(
  configuredRuntimeBaseUrl ||
    `https://raw.githubusercontent.com/${runtimeRepo}/${runtimeBranch}/data`
);

if (publishMode === "github-runtime-branch" && !runtimeBaseUrl) {
  throw new Error("PUBLIC_FRAME_PUBLIC_BASE_URL is required when PUBLIC_FRAME_PUBLISH_MODE=github-runtime-branch");
}

if (publishMode !== "github-runtime-branch" && !fallbackStaticBaseUrl && !runtimeBaseUrl) {
  throw new Error("PUBLIC_FRAME_PUBLIC_BASE_URL or PUBLIC_FILES_BASE_URL is required for public storyboard frames");
}

return items.map((inputItem) => {
  const item = inputItem.json;
  const runtimeRepoPath = toRuntimeRepoPath(item);
  const publicBaseUrl = publishMode === "github-runtime-branch"
    ? runtimeBaseUrl
    : normalizeBaseUrl(runtimeBaseUrl || fallbackStaticBaseUrl);
  const publicImageUrl = `${publicBaseUrl}/${publicPathFromRuntimeRepoPath(runtimeRepoPath)}`;

  return {
    json: {
      ...item,

      status: "storyboard_frame_publish_ready",
      source: "publish-storyboard-frames",

      runtime_branch: runtimeBranch,
      runtime_repo: runtimeRepo,
      runtime_public_base_url: runtimeBaseUrl,
      public_frame_publish_mode: publishMode,
      public_frame_publish_required: publishMode === "github-runtime-branch",
      public_frame_repo_path: runtimeRepoPath,
      public_frame_source_file_path: item.frame_file_path,
      public_frame_local_file_path: item.local_frame_file_path,
      public_frame_commit_message: `Publish storyboard frames for ${item.id || "idea_001"}`,

      public_image_url: publicImageUrl,
      public_image_url_source: publishMode === "github-runtime-branch"
        ? "runtime-storyboard-frames-branch"
        : "static-public-files-base-url",

      completed_at: new Date().toISOString()
    }
  };
});

const fs = require("fs");
const path = require("path");

const items = $input.all();

if (!items.length) {
  throw new Error("No scene duration items found for background music generation");
}

const enabled = String($env.BACKGROUND_MUSIC_ENABLED ?? "true").trim().toLowerCase() !== "false";
const style = String($env.BACKGROUND_MUSIC_STYLE || "simple-kids-toy-piano").trim();
const bpm = Number($env.BACKGROUND_MUSIC_BPM || 120);
const volumeDb = Number($env.BACKGROUND_MUSIC_VOLUME_DB || -26);
const fadeInSeconds = Number($env.BACKGROUND_MUSIC_FADE_IN_SECONDS || 0.2);
const fadeOutSeconds = Number($env.BACKGROUND_MUSIC_FADE_OUT_SECONDS || 0.5);
const sampleRate = 44100;
const id = items[0].json.id || "idea_001";
const outputDir = "/files/data/generated";
const outputPath = path.join(outputDir, `${id}-background-music.wav`);

function durationFromItems() {
  const summed = items.reduce((sum, inputItem) => {
    const item = inputItem.json;
    const value =
      Number(item.trimmed_duration_seconds || 0) ||
      Number(item.target_scene_duration_seconds || 0) ||
      Number(item.actual_duration_seconds || 0) ||
      Number(item.max_scene_duration_seconds || 0);
    return sum + (Number.isFinite(value) && value > 0 ? value : 0);
  }, 0);

  if (summed > 0) return summed;

  const fallback = Number(items[0].json.duration_seconds || items[0].json.source_video_pipeline_json?.duration_seconds || 18);
  return Number.isFinite(fallback) && fallback > 0 ? fallback : 18;
}

function midiToFrequency(midi) {
  return 440 * Math.pow(2, (midi - 69) / 12);
}

function writeWav(filePath, samples) {
  const dataSize = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataSize);

  buffer.write("RIFF", 0);
  buffer.writeUInt32LE(36 + dataSize, 4);
  buffer.write("WAVE", 8);
  buffer.write("fmt ", 12);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write("data", 36);
  buffer.writeUInt32LE(dataSize, 40);

  for (let i = 0; i < samples.length; i++) {
    const clamped = Math.max(-1, Math.min(1, samples[i]));
    buffer.writeInt16LE(Math.round(clamped * 32767), 44 + i * 2);
  }

  fs.writeFileSync(filePath, buffer);
}

function noteEnvelope(localTime, noteDuration) {
  const attack = Math.min(0.025, noteDuration * 0.2);
  const release = Math.min(0.16, noteDuration * 0.45);

  if (localTime < attack) return localTime / attack;
  if (localTime > noteDuration - release) return Math.max(0, (noteDuration - localTime) / release);
  return Math.exp(-2.6 * (localTime - attack));
}

function synthToyTone(frequency, localTime, noteDuration) {
  const envelope = noteEnvelope(localTime, noteDuration);
  const fundamental = Math.sin(2 * Math.PI * frequency * localTime);
  const bell = 0.45 * Math.sin(2 * Math.PI * frequency * 2 * localTime);
  const chime = 0.2 * Math.sin(2 * Math.PI * frequency * 3 * localTime);
  return (fundamental + bell + chime) * envelope;
}

function generateMusic(durationSeconds) {
  const safeBpm = Number.isFinite(bpm) && bpm > 40 ? bpm : 120;
  const beatSeconds = 60 / safeBpm;
  const stepSeconds = beatSeconds / 2;
  const melody = [60, 64, 67, 72, 67, 64, 62, 67, 65, 69, 72, 76, 72, 69, 67, 64];
  const harmony = [48, 55, 52, 55];
  const totalSamples = Math.ceil(durationSeconds * sampleRate);
  const samples = new Float32Array(totalSamples);
  const gain = Math.pow(10, volumeDb / 20);
  const fadeInSamples = Math.max(1, Math.floor(Math.max(0, fadeInSeconds) * sampleRate));
  const fadeOutSamples = Math.max(1, Math.floor(Math.max(0, fadeOutSeconds) * sampleRate));

  for (let i = 0; i < totalSamples; i++) {
    const time = i / sampleRate;
    const melodyStep = Math.floor(time / stepSeconds) % melody.length;
    const melodyLocal = time % stepSeconds;
    const harmonyStep = Math.floor(time / (beatSeconds * 2)) % harmony.length;
    const harmonyLocal = time % (beatSeconds * 2);
    const melodyTone = synthToyTone(midiToFrequency(melody[melodyStep]), melodyLocal, stepSeconds);
    const harmonyTone = 0.28 * synthToyTone(midiToFrequency(harmony[harmonyStep]), harmonyLocal, beatSeconds * 2);
    let fade = 1;

    if (i < fadeInSamples) fade *= i / fadeInSamples;
    if (i > totalSamples - fadeOutSamples) fade *= Math.max(0, (totalSamples - i) / fadeOutSamples);

    samples[i] = (melodyTone * 0.48 + harmonyTone * 0.32) * gain * fade;
  }

  return samples;
}

if (!enabled) {
  return items.map((inputItem) => ({
    json: {
      ...inputItem.json,
      background_music_enabled: false,
      background_music_file_path: null,
      background_music_duration_seconds: null,
      background_music_volume_db: volumeDb,
      background_music_style: style
    }
  }));
}

if (!Number.isFinite(volumeDb) || volumeDb > -6) {
  throw new Error(`BACKGROUND_MUSIC_VOLUME_DB must be a safe quiet value, got ${$env.BACKGROUND_MUSIC_VOLUME_DB || volumeDb}`);
}

const baseDuration = durationFromItems();
const durationSeconds = Number((baseDuration + 0.5).toFixed(3));

try {
  fs.mkdirSync(outputDir, { recursive: true });
  writeWav(outputPath, generateMusic(durationSeconds));
} catch (error) {
  throw new Error(`Background music generation failed: ${error.message}`);
}

if (!fs.existsSync(outputPath)) {
  throw new Error(`Background music file was not created: ${outputPath}`);
}

return items.map((inputItem) => ({
  json: {
    ...inputItem.json,
    background_music_enabled: true,
    background_music_file_path: outputPath,
    local_background_music_file_path: outputPath.replace("/files/data/", "data/"),
    background_music_duration_seconds: durationSeconds,
    background_music_volume_db: volumeDb,
    background_music_style: style,
    background_music_bpm: bpm,
    background_music_fade_in_seconds: fadeInSeconds,
    background_music_fade_out_seconds: fadeOutSeconds,
    background_music_source: "local-nodejs-pcm-wav"
  }
}));
